-- =============================================================================
-- Comprehensive Global Trade Analytics & Tariff Simulation Dataset
-- Sources: UN Comtrade, World Bank WITS, WTO Tariff Schedules (2018-2023)
-- Generated by etl/generate_comprehensive_datasets.py
-- =============================================================================

BEGIN;

-- 1. Data Sources
ON CONFLICT (source_id) DO UPDATE SET
  source_name = EXCLUDED.source_name, source_url = EXCLUDED.source_url;

-- 2. Countries (30 Sovereign Economies)
ON CONFLICT (country_id) DO UPDATE SET
  iso3 = EXCLUDED.iso3, iso2 = EXCLUDED.iso2, country_name = EXCLUDED.country_name, region = EXCLUDED.region, income_group = EXCLUDED.income_group;

-- 3. Products (20 HS2017 Codes)
ON CONFLICT (product_id) DO UPDATE SET
  product_description = EXCLUDED.product_description, hs_chapter = EXCLUDED.hs_chapter;

-- 4. Ingestion Batches
ON CONFLICT (batch_id) DO NOTHING;

-- 5. Trade Agreements
ON CONFLICT (agreement_id) DO UPDATE SET
  agreement_name = EXCLUDED.agreement_name, official_ref = EXCLUDED.official_ref, notes = EXCLUDED.notes;

-- Agreement Members
ON CONFLICT DO NOTHING;

-- 6. Trade Observations (2052 Bilateral Multi-Year Observations 2018-2023)
ON CONFLICT (reporter_country_id, partner_country_id, product_id, period_year, flow_direction, source_id)
DO UPDATE SET
  trade_value_usd = EXCLUDED.trade_value_usd, quantity = EXCLUDED.quantity, net_weight_kg = EXCLUDED.net_weight_kg;

-- 7. Tariff Policies (608 Statutory MFN & Preferential Schedule Records)
ON CONFLICT DO NOTHING;

-- 8. Pre-Configured Analytical Simulation Scenarios
ON CONFLICT (scenario_id) DO UPDATE SET
  scenario_name = EXCLUDED.scenario_name, description = EXCLUDED.description, baseline_period = EXCLUDED.baseline_period, scenario_status = EXCLUDED.scenario_status;

ON CONFLICT DO NOTHING;

-- 9. Synchronize Primary Key Sequences
SELECT setval(pg_get_serial_sequence('country', 'country_id'), coalesce(max(country_id), 1)) FROM country;
SELECT setval(pg_get_serial_sequence('product', 'product_id'), coalesce(max(product_id), 1)) FROM product;
SELECT setval(pg_get_serial_sequence('data_source', 'source_id'), coalesce(max(source_id), 1)) FROM data_source;
SELECT setval(pg_get_serial_sequence('ingestion_batch', 'batch_id'), coalesce(max(batch_id), 1)) FROM ingestion_batch;
SELECT setval(pg_get_serial_sequence('trade_agreement', 'agreement_id'), coalesce(max(agreement_id), 1)) FROM trade_agreement;
SELECT setval(pg_get_serial_sequence('trade_observation', 'trade_id'), coalesce(max(trade_id), 1)) FROM trade_observation;
SELECT setval(pg_get_serial_sequence('tariff_policy', 'tariff_policy_id'), coalesce(max(tariff_policy_id), 1)) FROM tariff_policy;
SELECT setval(pg_get_serial_sequence('tariff_scenario', 'scenario_id'), coalesce(max(scenario_id), 1)) FROM tariff_scenario;

COMMIT;